+using System.ComponentModel;
+using System.Net;
+using System.Text;
+using Microsoft.Agents.AI;
+using Microsoft.Extensions.AI;
+using OpenAI;
+
+// --- Configuration ---
+var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
+    ?? throw new InvalidOperationException(
+        "Set the OPENAI_API_KEY environment variable before running.");
+
+var modelId = "gpt-4o-mini-2024-07-18";
+
+// --- Build the chat client through MEAI abstraction ---
+IChatClient chatClient = new OpenAIClient(apiKey)
+    .GetChatClient(modelId)
+    .AsIChatClient();
+
+// --- Tool instances ---
+var researchNotes = new ResearchNotes();
+var webSearch = new WebSearchTool();
+
+// --- Register tools via AIFunctionFactory ---
+var tools = new AIFunction[]
+{
+    AIFunctionFactory.Create(webSearch.SearchAsync),
+    AIFunctionFactory.Create(researchNotes.SaveNote),
+    AIFunctionFactory.Create(researchNotes.GetAllNotes),
+};
+
+// --- Create the agent ---
+var agent = new ChatClientAgent(chatClient, "ResearchAgent")
+{
+    Description = "An AI research agent that searches the web and takes notes to produce a summary.",
+    Instructions = """
+        You are a research agent. When given a topic:
+        1. Search the web for relevant information using multiple queries.
+        2. Save important findings as notes using the note-taking tool.
+        3. After gathering enough information (at least 3-5 searches), retrieve all notes.
+        4. Produce a well-structured summary with key findings and sources.
+        Be thorough but concise. Always cite where information came from.
+        """,
+};
+
+// --- Get the research topic ---
+Console.Write("Enter a research topic: ");
+var topic = Console.ReadLine()?.Trim();
+if (string.IsNullOrEmpty(topic))
+{
+    Console.WriteLine("No topic provided. Exiting.");
+    return;
+}
+
+Console.WriteLine($"\nResearching: {topic}\n");
+
+// --- Run the agent ---
+var history = new List<ChatMessage>
+{
+    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
+};
+
+var options = new AgentInvokeOptions
+{
+    MaximumIterations = 15,
+    Tools = [.. tools],
+    Temperature = 0f,
+};
+
+await foreach (var message in agent.InvokeStreamingAsync(history, options))
+{
+    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
+    {
+        Console.Write(message.Text);
+    }
+}
+
+Console.WriteLine();
+
+// --- Tool: Web Search ---
+sealed class WebSearchTool
+{
+    private static readonly HttpClient s_http = new()
+    {
+        DefaultRequestHeaders =
+        {
+            { "User-Agent", "ResearchAgent/1.0" },
+            { "Accept", "text/html" },
+        },
+        Timeout = TimeSpan.FromSeconds(15),
+    };
+
+    [Description("Searches the web for the given query and returns a text snippet of the results. Use this to find information on any topic.")]
+    public async Task<string> SearchAsync(
+        [Description("The search query string")] string query)
+    {
+        try
+        {
+            var encoded = WebUtility.UrlEncode(query);
+            // Uses DuckDuckGo lite (HTML) — no API key required
+            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
+            var html = await s_http.GetStringAsync(url);
+
+            // Extract text content from the result snippets
+            var text = StripHtml(html);
+
+            const int maxLength = 3000;
+            if (text.Length > maxLength)
+                text = text[..maxLength] + "...";
+
+            return $"Search results for \"{query}\":\n{text}";
+        }
+        catch (Exception ex)
+        {
+            return $"Search failed for \"{query}\": {ex.Message}";
+        }
+    }
+
+    private static string StripHtml(string html)
+    {
+        var sb = new StringBuilder();
+        var inTag = false;
+        var lastWasSpace = false;
+
+        foreach (var ch in html)
+        {
+            if (ch == '<') { inTag = true; continue; }
+            if (ch == '>') { inTag = false; continue; }
+            if (inTag) continue;
+
+            if (char.IsWhiteSpace(ch))
+            {
+                if (!lastWasSpace) sb.Append(' ');
+                lastWasSpace = true;
+            }
+            else
+            {
+                sb.Append(ch);
+                lastWasSpace = false;
+            }
+        }
+
+        return WebUtility.HtmlDecode(sb.ToString().Trim());
+    }
+}
+
+// --- Tool: Note-Taking ---
+sealed class ResearchNotes
+{
+    private readonly List<string> _notes = [];
+
+    [Description("Saves a research note. Use this to record important findings, facts, or quotes discovered during research.")]
+    public string SaveNote(
+        [Description("The note content to save")] string note,
+        [Description("The source URL or description where this info was found")] string source)
+    {
+        var entry = $"[{_notes.Count + 1}] {note} (Source: {source})";
+        _notes.Add(entry);
+        return $"Note saved: #{_notes.Count}";
+    }
+
+    [Description("Retrieves all saved research notes. Call this when you are ready to compile your summary.")]
+    public string GetAllNotes()
+    {
+        if (_notes.Count == 0)
+            return "No notes saved yet.";
+
+        return $"All research notes ({_notes.Count} total):\n" + string.Join("\n", _notes);
+    }
+}

