            return $"Search failed for \"{query}\": {ex.Message}";
        }
    }

    private static string StripHtml(string html)
    {
        var sb = new StringBuilder();
        var inTag = false;
        var lastWasSpace = false;

        foreach (var ch in html)
        {
            if (ch == '<') { inTag = true; continue; }
            if (ch == '>') { inTag = false; continue; }
            if (inTag) continue;

            if (char.IsWhiteSpace(ch))
            {
                if (!lastWasSpace) sb.Append(' ');
                lastWasSpace = true;
            }
            else
            {
                sb.Append(ch);
                lastWasSpace = false;
            }
        }

        return WebUtility.HtmlDecode(sb.ToString().Trim());
    }
}

// --- Tool: Note-Taking ---
sealed class ResearchNotes
{
    private readonly List<string> _notes = [];

    [Description("Saves a research note. Use this to record important findings, facts, or quotes discovered during research.")]
    public string SaveNote(
        [Description("The note content to save")] string note,
        [Description("The source URL or description where this info was found")] string source)
    {
        var entry = $"[{_notes.Count + 1}] {note} (Source: {source})";
        _notes.Add(entry);
        return $"Note saved: #{_notes.Count}";
    }

    [Description("Retrieves all saved research notes. Call this when you are ready to compile your summary.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return $"All research notes ({_notes.Count} total):\n" + string.Join("\n", _notes);
    }
}

